const body = $json.body ?? $json;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Payload must be a JSON object');
if (typeof body.request !== 'string' || !body.request.trim()) throw new Error('request is required');
if (typeof body.source !== 'string' || !body.source.trim()) throw new Error('source is required');
const allowed = ['low','normal','high','urgent'];
const priority = body.priority ?? 'normal';
if (!allowed.includes(priority)) throw new Error('priority is invalid');
const deadline = body.deadline ?? null;
if (deadline && Number.isNaN(Date.parse(deadline))) throw new Error('deadline must be ISO-8601');
return [{json:{source:body.source.trim(),request:body.request.trim(),goal:body.goal ?? body.request.trim(),deadline,priority,request_id:body.request_id ?? null,metadata:body.metadata ?? {},schema_version:1}}];
